(()=>{
const rates={QAR:1,USD:0.274725,EUR:0.2345,GBP:0.2045,AED:1.0088,SAR:1.0302,KWD:0.0839,BHD:0.1033,OMR:0.1057,TND:0.812908,MAD:2.63508};
const symbols={QAR:'QAR',USD:'$',EUR:'€',GBP:'£',AED:'AED',SAR:'SAR',KWD:'KWD',BHD:'BHD',OMR:'OMR',TND:'TND',MAD:'MAD'};
let currency=localStorage.getItem('sultana-currency')||'QAR';if(!rates[currency])currency='QAR';
const fmt=n=>{const v=n*rates[currency];return `${symbols[currency]} ${v.toLocaleString(undefined,{minimumFractionDigits:currency==='QAR'?0:2,maximumFractionDigits:2})}`};
const priceSelectors='.price,.detail-price,#bag-total,.cart-total,.cart-subtotal,.subtotal,.total,[data-price-display],[data-money]';
const captureQar=el=>{if(el.dataset.qar)return;const m=el.textContent.match(/QAR\s*([\d,.]+)/i);if(m)el.dataset.qar=m[1].replace(/,/g,'')};
const convertText=()=>document.querySelectorAll(priceSelectors).forEach(el=>{captureQar(el);if(el.dataset.qar)el.textContent=fmt(Number(el.dataset.qar))});
const ensureOptions=()=>document.querySelectorAll('#currency-select').forEach(s=>{if(!s.querySelector('option[value="TND"]'))s.insertAdjacentHTML('beforeend','<option value="TND">🇹🇳 TND</option>');if(!s.querySelector('option[value="MAD"]'))s.insertAdjacentHTML('beforeend','<option value="MAD">🇲🇦 MAD</option>')});
const hideOldVisualMenu=()=>document.querySelectorAll('section').forEach(sec=>{const t=(sec.textContent||'').replace(/\s+/g,' ').toLowerCase();if((t.includes('explore sultana')||t.includes('discover our world'))&&t.includes('wedding')&&t.includes('hospitality'))sec.style.setProperty('display','none','important')});
const installHeader=()=>{const h=document.querySelector('header');if(!h)return;h.dataset.luxuryHeader='1';const brand=h.querySelector('.brand'),actions=h.querySelector('.header-actions');if(!brand||!actions)return;
let left=h.querySelector('.luxury-header-left');if(!left){left=document.createElement('div');left.className='luxury-header-left';left.innerHTML='<span>Qatar</span><span>|</span>';const cur=actions.querySelector('#currency-select'),lang=actions.querySelector('.language-switch');if(cur)left.appendChild(cur);left.insertAdjacentHTML('beforeend','<span>|</span>');if(lang)left.appendChild(lang);h.appendChild(left)}
let nav=h.querySelector('.luxury-main-nav');if(!nav){nav=document.createElement('nav');nav.className='luxury-main-nav';h.appendChild(nav)}nav.innerHTML='';[['Home','/'],['Perfumes','/shop/?collection=perfume#collection'],['Luxury Spray','/room-sprays/'],['Oud & Bakhoor','/oud-bakhoor/'],['B2B','/b2b/'],['Our Story','/our-story/'],['Contact','/contact/']].forEach(([l,u])=>{const a=document.createElement('a');a.href=u;a.textContent=l;nav.appendChild(a)});
Array.from(h.querySelectorAll('nav')).filter(n=>n!==nav).forEach(n=>n.style.setProperty('display','none','important'));
let style=document.getElementById('sultana-luxury-header');if(!style){style=document.createElement('style');style.id='sultana-luxury-header';document.head.appendChild(style)}style.textContent=`.language-switch{border:0!important;outline:0!important;box-shadow:none!important;background:transparent!important}@media(min-width:851px){header[data-luxury-header]{position:relative!important;display:block!important;height:160px!important;min-height:160px!important;padding:0!important;background:#fffdfa!important;border-bottom:1px solid #e5dccf!important}header[data-luxury-header] .luxury-header-left{position:absolute!important;left:5%!important;top:50px!important;display:flex!important;align-items:center!important;gap:12px!important;font-size:12px!important;z-index:20!important}header[data-luxury-header] .luxury-header-left .currency-select{border:0!important;background:transparent!important;width:auto!important;padding:4px 0!important}header[data-luxury-header]>.brand{position:absolute!important;left:50%!important;top:7px!important;transform:translateX(-50%)!important;width:92px!important;height:102px!important;margin:0!important;z-index:20!important}header[data-luxury-header]>.brand img{width:100%!important;height:100%!important;object-fit:contain!important}header[data-luxury-header]>.header-actions{position:absolute!important;right:5%!important;top:46px!important;display:flex!important;align-items:center!important;gap:18px!important;z-index:20!important}header[data-luxury-header]>.header-actions .currency-select,header[data-luxury-header]>.header-actions .language-switch{display:none!important}header[data-luxury-header]>.luxury-main-nav{position:absolute!important;display:flex!important;visibility:visible!important;opacity:1!important;left:0!important;right:0!important;bottom:0!important;height:48px!important;width:100%!important;justify-content:center!important;align-items:center!important;gap:clamp(25px,3vw,52px)!important;margin:0!important;padding:0 20px!important;background:#fffdfa!important;z-index:30!important;transform:none!important}header[data-luxury-header]>.luxury-main-nav a{display:inline-block!important;visibility:visible!important;opacity:1!important;color:#17130f!important;text-decoration:none!important;text-transform:uppercase!important;font-size:11px!important;font-weight:500!important;letter-spacing:.35px!important;line-height:48px!important;white-space:nowrap!important}header[data-luxury-header] .menu-toggle{display:none!important}}@media(max-width:850px){header[data-luxury-header] .luxury-header-left,header[data-luxury-header]>.luxury-main-nav{display:none!important}}`};
const sync=()=>{ensureOptions();document.querySelectorAll('#currency-select').forEach(s=>s.value=currency);convertText();installHeader();hideOldVisualMenu()};
document.addEventListener('change',e=>{if(e.target.id==='currency-select'){currency=e.target.value;localStorage.setItem('sultana-currency',currency);sync()}});new MutationObserver(()=>{convertText();hideOldVisualMenu()}).observe(document.body,{subtree:true,childList:true});document.addEventListener('DOMContentLoaded',sync);window.addEventListener('load',sync);window.SultanaCurrency={formatQAR:fmt,get:()=>currency,refresh:sync};
})();